// --- Identity Prepend ---
let identity_prepend = '';
try { identity_prepend = $('Build Identity Prepend').first().json.identity_prepend || ''; } catch(e) {}
// --- End Identity Prepend ---


const d = $input.item.json;

const research = d.research || d.diligence || '';

// Teardown vs standard. Mindmaker Live carries live builds and fresh news as well as
// Teardowns, so only pieces flagged as a teardown (or carrying a Commercial Mechanics
// Matrix / evidence table) get the teardown treatment. Legacy retired channel tag kept.
const isTeardown = !!(d.matrix_markdown || d.evidence_table)
  || String(d.target_channel || '').toLowerCase() === 'paid'
  || String(d.content_format || d.format || '').toLowerCase().indexOf('teardown') !== -1;
const content_format = isTeardown ? 'teardown' : 'standard';
const matrix = d.matrix_markdown ? '\n\nCOMPETITIVE MATRIX:\n' + d.matrix_markdown : '';
const chart = (d.chart_url && d.chart_url.includes('radar'))
  ? '\n\n[View Competitive Chart](' + d.chart_url + ')'
  : '';

const prompt = identity_prepend + `You are the assembly engine for the Omnichannel Content Factory. Your job is to produce a full, polished draft for the specified channel.

INPUT:
Hook: ${d.hook}
Target Audience: ${d.target_audience}
Contrarian Angle: ${d.contrarian_angle}
Target Channel: ${d.target_channel}
Format: ${content_format}
Diligence / Research Context:
${research}${matrix}${chart}

CHANNEL FORMATTING RULES:
- mindmaker_live with Format teardown: You are an investigative operator writing a commercial teardown for Mindmaker Live, the investigative format on how the open internet actually makes money in an AI world. 800-1200 words. Structure: open with a hard commercial provocation (never context-setting), build the argument using the real case studies and operator evidence from the diligence data, if a Markdown table or competitive matrix was provided in the diligence embed it naturally at the most relevant point in the argument, if a chart URL was provided embed it as a Markdown hyperlink using [View Competitive Chart](url) syntax - do NOT use image syntax. After the chart link, add a note: "Scores are based on the Mindmaker Live Commercial Mechanics Matrix. See evidence table below for sources and rationale." Write as a 16-year founder/operator who has seen the mechanics up close. Short punchy sentences, uneven rhythm, no corporate jargon, zero em-dashes, no summary at the end. Every abstract claim must be grounded in a tangible commercial mechanic.
- signal_noise: Podcast show notes + talking points structure, conversational, 3-5 key segments with timestamps
- mindmaker_live with Format standard: Executive education format, 600-900 words, framework-led, practical takeaways section. This is the default for Mindmaker Live and covers live builds and fresh news as well as frameworks. Do not turn it into a teardown.
- linkedin: 250-400 words, no em dashes, hook in first line, 3-5 punchy paragraphs, ends with a question or provocation
- built: Podcast/IG hybrid, punchy narrative, 400-600 words, audio-first pacing
- vertical_video: Script format, hook in first 3 seconds, 60-90 second total length, visual cue callouts in brackets
- dynamic: Follow any embedded instructions in the hook field

Write the full draft now. Do not include preamble or meta-commentary. Output the content only.`;

// Return as object - n8n will serialize it correctly
const assembly_body = {
  model: 'claude-sonnet-4-6',
  max_tokens: 4000,
  messages: [{ role: 'user', content: prompt }]
};

return {
  json: {
    ...d,
    assembly_body
  }
};

// Fail-loud Normalize v2.
// Never throws. Emits ONE item with either:
//   { is_error: false, generated_content, doc_title, drive_folder_id, _provider, _word_count }
// OR:
//   { is_error: true, error_message, error_source, error_detail, failure_hook, failure_channel, failure_provider }
//
// Downstream "If: Is Error?" node splits the two paths.

const items = $input.all();
if (!items || items.length === 0) {
  return [{ json: { is_error: true, error_message: 'No input items', error_source: 'normalize', error_detail: 'Normalize received no items from any LLM branch' } }];
}

const item = items[0];
const raw = item.json || {};

// Load context for error messages
let hook = 'unknown';
let channel = 'unknown';
let driveFolderId = '';
try {
  const noopItems = $('No Operation, do nothing').all();
  if (noopItems && noopItems.length > 0) {
    const noop = noopItems[0].json || {};
    hook = noop.hook || 'unknown';
    channel = noop.target_channel || 'unknown';
    driveFolderId = noop.drive_folder_id || '';
  }
} catch (e) {}

function err(msg, source, detail) {
  return [{ json: {
    is_error: true,
    error_message: String(msg).slice(0, 300),
    error_source: source,
    error_detail: String(detail || '').slice(0, 600),
    failure_hook: hook,
    failure_channel: channel,
    failure_provider: source,
  } }];
}

// 1. Wrapped error responses (Gemini neverError=true returns 200 with error body)
if (raw && raw.error && typeof raw.error === 'object' && 'code' in raw.error) {
  const code = raw.error.code || 'unknown';
  return err(`Provider returned error code ${code}`, 'gemini-or-openai', raw.error.message || JSON.stringify(raw.error));
}

// 2. n8n node-error passthrough (Anthropic onError=continueErrorOutput emits error object)
if (raw && raw.error && typeof raw.error === 'object' && (raw.error.name === 'NodeApiError' || raw.error.description)) {
  const desc = raw.error.description || raw.error.message || 'no detail';
  return err('Anthropic API error', 'anthropic', desc);
}

// 3. Parse successful response shapes
let text = '';
let provider = 'unknown';

if (Array.isArray(raw.content) && raw.content.length > 0 && raw.content[0].text) {
  text = raw.content[0].text;
  provider = 'anthropic';
} else if (Array.isArray(raw.choices) && raw.choices.length > 0 && raw.choices[0].message && raw.choices[0].message.content) {
  text = raw.choices[0].message.content;
  provider = 'openai';
} else if (Array.isArray(raw.candidates) && raw.candidates.length > 0 &&
           raw.candidates[0].content && Array.isArray(raw.candidates[0].content.parts) &&
           raw.candidates[0].content.parts[0] && raw.candidates[0].content.parts[0].text) {
  text = raw.candidates[0].content.parts[0].text;
  provider = 'gemini';
}

const trimmed = (text || '').trim();
if (!trimmed) {
  return err('No usable content in LLM response', 'no-content', `Response keys: ${Object.keys(raw).join(',').slice(0, 200)}`);
}

const wordCount = trimmed.split(/\s+/).filter(w => w.length > 0).length;
if (wordCount < 50) {
  return err(`LLM content too thin (${wordCount} words)`, provider, `Content preview: ${trimmed.slice(0, 200)}`);
}

const cleaned = trimmed.replace(/\u2014/g, ' - ');
const docTitle = '[' + String(channel).toUpperCase() + '] ' + String(hook).slice(0, 60) + ' - ' + new Date().toISOString().slice(0, 10);

return [{
  json: {
    is_error: false,
    generated_content: cleaned,
    doc_title: docTitle,
    drive_folder_id: driveFolderId,
    _provider: provider,
    _word_count: wordCount,
  }
}];

const raw = $input.item.json.choices?.[0]?.message?.content || $input.item.json.diligence || '';

const FIXED_DIMENSIONS = ['Revenue Leverage', 'Data Moat Depth', 'Switching Cost Architecture', 'Margin Trajectory', 'Principal Alignment'];

let parsed = {
  research: raw,
  matrix_detected: false,
  matrix_rationale: 'Could not parse Perplexity response',
  matrix_title: null,
  matrix_dimensions: FIXED_DIMENSIONS,
  matrix_players: [],
  matrix_markdown: null,
  matrix_scores: [],
  evidence_table: null,
  hook: $('Cleo Webhook').item.json.body.hook,
  target_audience: $('Cleo Webhook').item.json.body.target_audience,
  contrarian_angle: $('Cleo Webhook').item.json.body.contrarian_angle,
  target_channel: $('Cleo Webhook').item.json.body.target_channel,
  drive_folder_id: '1Rb4PZPGLmoczM2uxmjeVN5uilqm0_qTh'
};

function tryParseJson(str) {
  // Attempt 1: direct parse
  try { return JSON.parse(str); } catch(e) {}

  // Attempt 2: strip common issues - trailing commas before } or ]
  try {
    const cleaned = str
      .replace(/,\s*([}\]])/g, '$1')  // trailing commas
      .replace(/[\x00-\x1F\x7F]/g, ' '); // control chars except \n
    return JSON.parse(cleaned);
  } catch(e) {}

  // Attempt 3: extract just the outer object, truncating at first parse error
  // by progressively truncating from the end
  const match = str.match(/^\s*\{/);
  if (match) {
    for (let len = str.length; len > 100; len = Math.floor(len * 0.9)) {
      const chunk = str.slice(0, len);
      // Find last complete field boundary
      const lastComma = chunk.lastIndexOf(',');
      const lastBrace = chunk.lastIndexOf('}');
      const truncAt = Math.max(lastComma, lastBrace);
      if (truncAt < 10) continue;
      try {
        // Try to close the object
        const attempt = chunk.slice(0, truncAt) + '\n}';
        const obj = JSON.parse(attempt);
        return obj;
      } catch(e) {}
    }
  }

  return null;
}

try {
  // Find JSON block in response
  const jsonMatch = raw.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    const obj = tryParseJson(jsonMatch[0]);
    if (obj) {
      parsed.research = obj.research || raw;
      parsed.matrix_detected = obj.matrix_detected === true;
      parsed.matrix_rationale = obj.matrix_rationale || '';
      parsed.matrix_title = obj.matrix_title || null;
      parsed.matrix_dimensions = FIXED_DIMENSIONS;
      parsed.matrix_players = obj.matrix_players || [];
      // Sanitize matrix_markdown to remove any characters that break string injection
      parsed.matrix_markdown = obj.matrix_markdown || null;
      parsed.matrix_scores = obj.matrix_scores || [];

      // If parse partially succeeded but matrix_detected not found, check raw
      if (!parsed.matrix_detected) {
        const mdMatch = raw.match(/"matrix_detected"\s*:\s*true/i);
        if (mdMatch) {
          parsed.matrix_detected = true;
          // Try to get scores from regex if JSON parse was partial
          if (!parsed.matrix_scores.length) {
            const titleMatch = raw.match(/"matrix_title"\s*:\s*"([^"]+)"/);
            if (titleMatch) parsed.matrix_title = titleMatch[1];
          }
        }
      }

      // Build evidence table
      if (parsed.matrix_scores && parsed.matrix_scores.length > 0) {
        let evidenceRows = [];
        parsed.matrix_scores.forEach(player => {
          if (player.evidence) {
            FIXED_DIMENSIONS.forEach(dim => {
              const ev = player.evidence[dim];
              if (ev) {
                evidenceRows.push({
                  player: player.name,
                  dimension: dim,
                  score: ev.score || player[dim],
                  // Sanitize source/rationale - strip pipe chars that break markdown tables
                  source: (ev.source || 'No source provided').replace(/\|/g, '/'),
                  rationale: (ev.rationale || '').replace(/\|/g, '/')
                });
              }
            });
          }
        });

        if (evidenceRows.length > 0) {
          let table = '| Player | Dimension | Score | Evidence | Rationale |\n';
          table += '|--------|-----------|-------|----------|-----------|\n';
          evidenceRows.forEach(row => {
            table += `| ${row.player} | ${row.dimension} | ${row.score} | ${row.source} | ${row.rationale} |\n`;
          });
          parsed.evidence_table = table;
        }
      }
    }
  }

  // Fallback: if still no matrix_detected, check raw text
  if (!parsed.matrix_detected) {
    const mdMatch = raw.match(/"matrix_detected"\s*:\s*true/i);
    if (mdMatch) parsed.matrix_detected = true;
  }

} catch(e) {
  parsed.research = raw;
  parsed.matrix_detected = false;
}

return { json: parsed };

// Get raw markdown from generated_content (NOT the HTML output of Markdown to HTML node)
const md = $input.item.json.generated_content || '';
const title = $input.item.json.doc_title;
const folderId = $input.item.json.drive_folder_id;

// Convert markdown to clean HTML suitable for Google Docs
function mdToHtml(text) {
  const lines = text.split('\n');
  const out = [];
  let i = 0;

  while (i < lines.length) {
    const line = lines[i];

    // Check for table block - consecutive lines with pipes
    if (line.trim().startsWith('|') && line.trim().endsWith('|')) {
      const tableLines = [];
      while (i < lines.length && lines[i].trim().startsWith('|')) {
        tableLines.push(lines[i]);
        i++;
      }
      out.push(buildTable(tableLines));
      continue;
    }

    // Headings
    if (/^#{1,6}\s/.test(line)) {
      const level = line.match(/^(#+)/)[1].length;
      const content = line.replace(/^#+\s+/, '');
      out.push(`<h${level}>${inlineFormat(content)}</h${level}>`);
      i++;
      continue;
    }

    // Empty line = paragraph break
    if (line.trim() === '') {
      i++;
      continue;
    }

    // Regular paragraph
    out.push(`<p style="margin-bottom:10pt">${inlineFormat(line.trim())}</p>`);
    i++;
  }

  return out.join('\n');
}

function buildTable(lines) {
  // Filter out separator rows (lines with only dashes, pipes, colons, spaces)
  const dataLines = lines.filter(l => !/^\|[\s\-\|:]+\|$/.test(l.trim()));
  if (dataLines.length === 0) return '';

  const parseRow = (line) => {
    return line.trim()
      .replace(/^\|/, '').replace(/\|$/, '')
      .split('|')
      .map(c => c.trim());
  };

  const header = parseRow(dataLines[0]);
  const rows = dataLines.slice(1).map(parseRow);

  let html = '<table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse;width:100%">';
  html += '<thead><tr>';
  header.forEach(h => {
    html += `<th style="background:#f0f0f0;font-weight:bold;padding:6px">${inlineFormat(h)}</th>`;
  });
  html += '</tr></thead><tbody>';
  rows.forEach(row => {
    html += '<tr>';
    row.forEach(c => {
      html += `<td style="padding:6px">${inlineFormat(c)}</td>`;
    });
    html += '</tr>';
  });
  html += '</tbody></table>';
  return html;
}

function inlineFormat(text) {
  // Bold
  text = text.replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>');
  text = text.replace(/__(.+?)__/g, '<strong>$1</strong>');
  // Italic
  text = text.replace(/\*(.+?)\*/g, '<em>$1</em>');
  text = text.replace(/_(.+?)_/g, '<em>$1</em>');
  // Links [text](url) - must handle URLs with literal parens like rgba(255,99,132,0.2)
  // Strategy: find each [text]( marker, then scan forward tracking paren depth to find real closing )
  let result = '';
  let i = 0;
  while (i < text.length) {
    const bracketStart = text.indexOf('[', i);
    if (bracketStart === -1) { result += text.slice(i); break; }
    const bracketEnd = text.indexOf('](', bracketStart);
    if (bracketEnd === -1) { result += text.slice(i); break; }
    const linkText = text.slice(bracketStart + 1, bracketEnd);
    // Scan from after ]( tracking paren depth
    let depth = 1;
    let j = bracketEnd + 2;
    while (j < text.length && depth > 0) {
      if (text[j] === '(') depth++;
      else if (text[j] === ')') depth--;
      j++;
    }
    if (depth !== 0) { result += text.slice(i, bracketEnd + 1); i = bracketEnd + 1; continue; }
    const url = text.slice(bracketEnd + 2, j - 1);
    result += text.slice(i, bracketStart);
    result += '<a href="' + url + '">' + linkText + '</a>';
    i = j;
  }
  text = result;
  // Inline code
  text = text.replace(/`([^`]+)`/g, '<code>$1</code>');
  return text;
}

// Build evidence table HTML if present
let evidenceTableHtml = '';
const evidenceTableMd = $input.item.json.evidence_table;
if (evidenceTableMd) {
  const evLines = evidenceTableMd.trim().split('\n');
  const evDataLines = evLines.filter(l => !/^\|[-| :]+\|$/.test(l.trim()));
  if (evDataLines.length > 1) {
    const parseRow = (line) => line.trim().replace(/^\|/, '').replace(/\|$/, '').split('|').map(c => c.trim());
    const evHeader = parseRow(evDataLines[0]);
    const evRows = evDataLines.slice(1).map(parseRow);
    evidenceTableHtml = '<h2>Scoring Evidence</h2>';
    evidenceTableHtml += '<p style="margin-bottom:8pt;font-size:9pt;color:#666">Scores are based on the Mindmaker Live Commercial Mechanics Matrix. Each score derives from a specific piece of public evidence.</p>';
    evidenceTableHtml += '<table border="1" cellpadding="5" cellspacing="0" style="border-collapse:collapse;width:100%;font-size:9pt">';
    evidenceTableHtml += '<thead><tr>' + evHeader.map(h => '<th style="background:#e8f0fe;font-weight:bold;padding:5px">' + h + '</th>').join('') + '</tr></thead><tbody>';
    evRows.forEach(row => {
      evidenceTableHtml += '<tr>' + row.map(c => '<td style="padding:5px;vertical-align:top">' + c + '</td>').join('') + '</tr>';
    });
    evidenceTableHtml += '</tbody></table>';
  }
}

let bodyHtml = mdToHtml(md) + evidenceTableHtml;
let html = `<html><head><style>
  body { font-family: Arial, sans-serif; font-size: 11pt; line-height: 1.5; }
  h1 { font-size: 18pt; margin-bottom: 12pt; }
  h2 { font-size: 14pt; margin-top: 16pt; margin-bottom: 8pt; }
  h3 { font-size: 12pt; margin-top: 14pt; margin-bottom: 6pt; }
  p { margin-top: 0; margin-bottom: 10pt; }
  table { border-collapse: collapse; width: 100%; margin-bottom: 12pt; }
  th { background: #f0f0f0; font-weight: bold; padding: 6pt; border: 1px solid #ccc; }
  td { padding: 6pt; border: 1px solid #ccc; }
  a { color: #1155CC; }
</style></head><body>
<h1>${title}</h1>
` + bodyHtml + `</body></html>`;

const boundary = 'gcf_boundary_n8n_fixed_abc';

const metadata = JSON.stringify({
  name: title,
  mimeType: 'application/vnd.google-apps.document',
  parents: [folderId]
});

const body = [
  '--' + boundary,
  'Content-Type: application/json; charset=UTF-8',
  '',
  metadata,
  '--' + boundary,
  'Content-Type: text/html; charset=UTF-8',
  '',
  html,
  '--' + boundary + '--'
].join('\r\n');

return {
  json: {
    ...$input.item.json,
    multipart_body: body,
    multipart_boundary: boundary
  }
};

// Build identity prepend from Agent Brief + Voice Rules + Agent Plan
const briefRaw = $('Load Agent Brief').first().json;
const voiceRaw = $('Load Voice Rules').first().json;
const planRaw  = $('Load Agent Plan').first().json;

// Handle array response from Supabase REST
const briefArr = Array.isArray(briefRaw) ? briefRaw : (briefRaw.data || [briefRaw]);
const voiceArr = Array.isArray(voiceRaw) ? voiceRaw : (voiceRaw.data || [voiceRaw]);
const planArr  = Array.isArray(planRaw)  ? planRaw  : (planRaw.data  || [planRaw]);

const brief = briefArr[0]?.brief_content || '';
const voice = voiceArr[0]?.value || 'Write as Krish Raja. Direct, casual, no fluff. No em dashes. Short paragraphs. Max 120 words outbound.';
const plan  = planArr[0] || {};

// Stale-Plan gating: null or > 72h triggers READ-ONLY mode downstream
const STALE_HOURS = 72;
let plan_stale = false;
if (!plan.last_rendered_at) {
  plan_stale = true;
} else {
  const ageHours = (Date.now() - new Date(plan.last_rendered_at).getTime()) / 3600000;
  plan_stale = ageHours > STALE_HOURS;
}

const planBlock = (plan.current_phase || plan.objective) ? (
  'CURRENT PLAN:\n' +
  (plan.current_phase  ? `Phase: ${plan.current_phase}\n` : '') +
  (plan.objective      ? `Objective: ${plan.objective}\n` : '') +
  (plan.next_milestone ? `Next milestone: ${plan.next_milestone}\n` : '') +
  (plan.blockers       ? `Blockers: ${plan.blockers}\n` : '') +
  (plan.doc_link       ? `Plan doc: ${plan.doc_link}\n` : '') +
  (plan.status         ? `Status: ${plan.status}\n` : '') +
  '\n'
) : '';

const identity_prepend =
  (brief ? 'AGENT BRIEF:\n' + brief + '\n\n' : '') +
  planBlock +
  'VOICE RULES:\n' + voice + '\n\n';

const items = $input.all();
return items.map(item => ({
  json: { ...item.json, identity_prepend, plan_stale }
}));

// Auto-inserted: rebuild gemini_body from anthropic request context
// The error branch passes through input. We need the original anthropic messages.
// Strategy: look at the immediately-preceding Anthropic node input via $json
// and fall back to walking upstream nodes.

const items = $input.all();
const out = [];
for (const item of items) {
  // item.json typically contains either the Build Prompt output or error context
  const src = item.json || {};
  let messages = [];
  let maxTokens = 1024;
  let systemPrompt = null;

  // Try common shapes
  if (src.anthropic_body && src.anthropic_body.messages) {
    messages = src.anthropic_body.messages;
    maxTokens = src.anthropic_body.max_tokens || 1024;
    systemPrompt = src.anthropic_body.system || null;
  } else if (src.messages) {
    messages = src.messages;
    maxTokens = src.max_tokens || 1024;
    systemPrompt = src.system || null;
  }

  // Build Gemini-compatible body
  let promptText = '';
  if (systemPrompt) promptText += systemPrompt + '\n\n';
  for (const m of messages) {
    const content = typeof m.content === 'string' ? m.content : JSON.stringify(m.content);
    promptText += (m.role === 'user' ? content : '[assistant]: ' + content) + '\n\n';
  }
  const gemini_body = {
    contents: [{ parts: [{ text: promptText.trim() }] }],
    generationConfig: { maxOutputTokens: maxTokens, temperature: 0.6 }
  };
  out.push({ json: { ...src, gemini_body } });
}
return out;

// Build Telegram alert from the structured error emitted by Normalize.
const items = $input.all();
const d = (items && items.length > 0) ? (items[0].json || {}) : {};

const errMsg = d.error_message || 'unknown';
const errSource = d.error_source || 'unknown';
const errDetail = d.error_detail || '';
const hook = d.failure_hook || 'unknown';
const channel = d.failure_channel || 'unknown';

const ts = new Date().toISOString().replace('T', ' ').slice(0, 19) + ' UTC';

const text = [
  'ðŸš¨ *Cleo content generation failed*',
  '',
  '*Channel:* `' + channel + '`',
  '*Hook:* ' + String(hook).slice(0, 120),
  '*Provider:* `' + errSource + '`',
  '',
  '*Error:* ' + String(errMsg).slice(0, 300).replace(/`/g, "'"),
  '',
  '*Detail:*',
  '`' + String(errDetail).slice(0, 500).replace(/`/g, "'") + '`',
  '',
  '_' + ts + '_',
  '_No draft was uploaded to Drive._'
].join('\n');

return [{ json: { telegram_payload: { chat_id: '6773796504', parse_mode: 'Markdown', text: text } } }];
